const comprados = $node["Normalizar payload"].json.items || [];
const catalogo = $node["Buscar conteudo de entrega"].json || [];

const partes = [];   // mensagens de texto
const midias = [];   // documentos/audios enviados ANTES do texto
const faltando = [];
let assinatura = null; // produto recorrente comprado nesta venda, se houver

for (const item of comprados) {
  const p = catalogo.find(c => c.produto_id === item.produto_id || c.nome === item.title);
  const nome = (p && p.nome) || item.title || 'seu item';

  if (p && Array.isArray(p.entrega_midia)) {
    for (const mid of p.entrega_midia) {
      if (mid && mid.url) midias.push(mid);
    }
  }

  if (p && p.mensalidade_centavos) {
    assinatura = {
      produto_id: p.produto_id,
      valor_centavos: p.mensalidade_centavos,
      trial_dias: p.trial_dias || 0
    };
  }

  if (p && p.entrega_texto) {
    let txt = p.entrega_texto;

    // Link individual da Comunidade: 1 acesso por compradora. Se a fila de
    // links acabou, NAO manda placeholder cru nem link quebrado -- avisa que
    // chega em seguida e cai no alerta para o Rodrigo repor a fila.
    if (txt.includes('{LINK_COMUNIDADE}')) {
      const cfg = $node["Buscar link da comunidade"].json;
      const linha = Array.isArray(cfg) ? cfg[0] : cfg;
      let url = (linha && linha.valor) || null;
      // placeholder nao preenchido conta como ausente: melhor avisar que chega
      // em seguida do que mandar "<<COLE_AQUI_O_LINK_DO_GRUPO>>" para a cliente
      if (url && url.startsWith('<<')) url = null;
      if (url) {
        txt = txt.split('{LINK_COMUNIDADE}').join(url);
      } else {
        txt = 'Seja bem-vinda a Comunidade do Padre Frei! Seu link de acesso chega em seguida, aqui mesmo por este WhatsApp.';
        faltando.push(nome + ' (link do grupo nao cadastrado)');
      }
    }

    partes.push(txt);
  } else if (!(p && Array.isArray(p.entrega_midia) && p.entrega_midia.length)) {
    // so conta como faltando se nao tiver NEM texto NEM midia
    faltando.push(nome);
    partes.push('Sobre *' + nome + '*: seu acesso chega em seguida, aqui mesmo por este WhatsApp.');
  }
}

// Nunca deixar a cliente sem mensagem alguma depois de pagar.
const texto = partes.length
  ? partes.join('\n\n')
  : 'Seu acesso chega em seguida, aqui mesmo por este WhatsApp.';

return [{ json: { texto, midias, assinatura, faltando, tem_falta: faltando.length > 0 } }];

const to = $node["Normalizar payload"].json.lead_id;
const e = $node["Montar entrega"].json;

const saida = [];
for (const m of (e.midias || [])) {
  const item = { to, tipo: m.tipo === 'audio' ? 'audio' : 'documento', url: m.url };
  if (m.filename) item.filename = m.filename;
  if (m.legenda) item.legenda = m.legenda;
  saida.push({ json: item });
}
saida.push({ json: { to, tipo: 'text', texto: e.texto } });
return saida;

const m = $node["Montar entrega"].json;
const wa = $node["Normalizar payload"].json.lead_id;
return [{ json: { to: '5517991999546', tipo: 'text', texto: '⚠️ Entrega pendente.
Cliente: ' + wa + '
Sem conteudo cadastrado para: ' + m.faltando.join(', ') + '
Ela ja pagou e foi avisada de que o acesso chega em seguida. Entregue na mao e preencha entrega_texto em produtos.' } }];

// Valida a assinatura HMAC-SHA256 do BravoPay.
// Sem isto, quem descobrir a URL do webhook forja um transaction.paid e recebe
// a entrega sem pagar -- o fluxo inteiro confia neste payload.
const crypto = require('crypto');

const entrada = $node["BravoPay IN"].json;
const headers = entrada.headers || {};
const bruto   = entrada.body;   // string, por causa do rawBody no webhook

const assinatura = headers['bravopay-signature'] || headers['x-bravopay-signature'] || '';

// O segredo vem da tabela `configuracoes`. O PikaPods nao expoe $env e um node
// Code nao consegue ler Credential do n8n -- o banco e o unico lugar comum.
const cfg = $node["Buscar segredo do webhook"].json;
const linha = Array.isArray(cfg) ? cfg[0] : cfg;
const segredo = (linha && linha.valor) || '';

function recusar(motivo) {
  return [{ json: { valido: false, motivo, corpo: null } }];
}

if (!segredo || segredo.startsWith('<<')) return recusar('segredo do webhook nao cadastrado em configuracoes');
if (!assinatura) return recusar('requisicao sem cabecalho de assinatura');

// formato: t=<timestamp>,v1=<hex>
const partes = Object.fromEntries(
  String(assinatura).split(',').map(p => {
    const i = p.indexOf('=');
    return [p.slice(0, i).trim(), p.slice(i + 1).trim()];
  })
);
const ts = partes.t;
const v1 = partes.v1;
if (!ts || !v1) return recusar('cabecalho de assinatura malformado');

// Janela de 5 min: sem isso, uma requisicao legitima capturada uma vez pode ser
// reenviada para sempre, porque a assinatura dela continua valendo.
const idadeSeg = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
if (!Number.isFinite(idadeSeg) || idadeSeg > 300) {
  return recusar('timestamp fora da janela de 5 minutos (' + idadeSeg + 's)');
}

const corpoStr = typeof bruto === 'string' ? bruto : JSON.stringify(bruto);
const esperado = crypto.createHmac('sha256', segredo)
                       .update(ts + '.' + corpoStr)
                       .digest('hex');

// timingSafeEqual: comparar com === vaza o tamanho do prefixo correto pelo
// tempo de resposta, o que permite descobrir a assinatura byte a byte.
const a = Buffer.from(esperado, 'hex');
const b = Buffer.from(String(v1), 'hex');
const confere = a.length === b.length && crypto.timingSafeEqual(a, b);

if (!confere) return recusar('assinatura nao confere');

return [{ json: { valido: true, motivo: null, corpo: JSON.parse(corpoStr) } }];

// Normaliza o payload do BravoPay para a forma que o resto do fluxo espera.
// O BravoPay NAO manda items[] -- manda um amount_cents unico. Os produto_id
// comprados viajam em metadata.produtos, gravado na criacao da cobranca.
const c = $node["Validar assinatura"].json.corpo || {};
const d = c.data || {};
const meta = d.metadata || {};

// metadata so aceita valores simples, entao produtos vai como "a,b,c".
const ids = String(meta.produtos || '')
  .split(',').map(s => s.trim()).filter(Boolean);

// Reconstroi items[] no formato que registrar_compra() espera.
const items = ids.map(id => ({ produto_id: id }));

return [{ json: {
  tipo:        c.type || '',
  transacao:   d.id || null,
  lead_id:     d.external_reference || null,
  valor_cents: d.amount_cents || 0,
  metodo:      (d.method || '').toLowerCase(),
  items,
  metadata:    meta,
  tracking:    d.tracking || {},
  cliente:     d.customer || {},
} }];

const r = $node["Criar link de assinatura (Pagar.me)"].json || {};
const url = r.url || null;
const to = $node["Normalizar payload"].json.lead_id;
const a = $node["Montar entrega"].json.assinatura || {};
const valor = ((a.valor_centavos || 0) / 100).toFixed(2).replace('.', ',');

// Sem link nao inventa mensagem: a cliente ja pagou a entrada e recebeu o
// produto. Falhar aqui nao pode virar cobranca fantasma nem promessa vazia --
// o alerta vai para o Rodrigo resolver na mao.
if (!url) {
  return [{ json: { to: '5517991999546', tipo: 'text', texto:
    '⚠️ Pagar.me nao gerou o link de assinatura do lead ' + to +
    ' (produto ' + (a.produto_id || '?') + '). Ela pagou a entrada e recebeu o acesso, ' +
    'mas a mensalidade nao foi cadastrada. Resolver na mao.' } }];
}

return [{ json: { to, tipo: 'text', texto:
  'Seus primeiros 30 dias sao um presente 🙏\n\n' +
  'Para continuar depois desse periodo, cadastre seu cartao aqui: ' + url + '\n\n' +
  'Sao R$ ' + valor + ' por mes, a primeira cobranca so acontece no 31o dia, ' +
  'e voce cancela quando quiser.' } }];
